from api.health import bank_findings


class DB:
    def __init__(self, bank, carried):
        self.v = {'bank': bank, 'fund_master': carried}

    def scalar(self, sql):
        return self.v['bank'] if 'bank' in sql else self.v['fund_master']


def test_carried_gold_counts():
    assert bank_findings(DB(0, 20000)) == []
